select id, customer_id, device, browser, started_at, country, last_value(country, true) over (partition by browser order by started_at, id rows between unbounded preceding and current row) as last_known_country, last_value(country) ignore nulls over (order by started_at, id rows between unbounded preceding and current row) as last_known_country_2, first_value(browser) ignore nulls over w_grp as first_known_browser from sessions window w_grp as (partition by customer_id order by started_at, id rows between unbounded preceding and current row);
